import limited_client as robot, numpy as np
from PIL import Image
for cam in (1,2):
    obs=robot.observe(camera=cam)
    Image.fromarray(obs['rgb']).save(f'/app/output/fresh_scene_{cam}.png')
    r=obs['robot']; K,T,d=obs['intrinsic'],obs['camera_to_world'],obs['depth_m']
    c=np.linalg.inv(T)@np.r_[r['tcp_position'],1.]; uv=K@c[:3]
    print('\nCAM',cam,'robot',r,'status',robot.status())
    print('tcp_pixel',np.round(uv[:2]/uv[2],1),'tcp_cam',np.round(c[:3],3))
    if cam==2:
        pts={'rose_head':(145,452),'rose_stem_near':(165,454),'rose_stem_mid':(190,454),'vase_center':(116,450),'vase_opening':(116,432)}
    else:
        pts={'rose_head':(337,295),'rose_stem':(305,330),'vase_rim':(421,330),'vase_body':(430,360)}
    for name,(u,v) in pts.items():
        a=d[max(0,v-2):v+3,max(0,u-2):u+3]; z=float(np.nanmedian(a))
        q=np.linalg.inv(K)@np.array([u,v,1.])*z; w=T@np.r_[q,1.]
        print(name,(u,v),'depth',round(z,3),'world',np.round(w[:3],3),'range',np.round(np.nanpercentile(a,[10,90]),3))
